import { Component, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-example',
  template: `<button (click)="onClick()">Action</button>`
})
export class ExampleComponent {
  @Output() action = new EventEmitter<void>();

  onClick() {
    this.action.emit();
  }
}

